import{_ as e,o as i,c as s,a0 as a}from"./chunks/framework.CzVS_xMp.js";const l="data:image/svg+xml;base64,",I="data:image/svg+xml;base64,",j=JSON.parse('{"title":"Efficient LLM Inference Systems","description":"","frontmatter":{},"headers":[],"relativePath":"inference/efficient-llm-inference-systems/week01/index.md","filePath":"inference/efficient-llm-inference-systems/week01/index.md","lastUpdated":1788490169000}'),n={name:"inference/efficient-llm-inference-systems/week01/index.md"};function g(h,t,r,d,p,o){return i(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="efficient-llm-inference-systems" tabindex="-1">Efficient LLM Inference Systems <a class="header-anchor" href="#efficient-llm-inference-systems" aria-label="Permalink to &quot;Efficient LLM Inference Systems&quot;">​</a></h1><h2 id="week-1-ttft-tpot-batch-throughput" tabindex="-1">Week 1: TTFT, TPOT, Batch Throughput <a class="header-anchor" href="#week-1-ttft-tpot-batch-throughput" aria-label="Permalink to &quot;Week 1: TTFT, TPOT, Batch Throughput&quot;">​</a></h2><p>This chapter measures how prompt length and batch size affect latency and throughput in decoder-only LLM inference.</p><p>The experiment uses <code>Qwen/Qwen2.5-3B-Instruct</code>. A 3B model is used instead of the original 7B model so the run fits cleanly in a 16GB VRAM environment without CPU offload.</p><h3 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/ai-data-center-systems/inference</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HF_HOME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/data/LLM/models/hugging-face</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chat01/labs-01-sweep.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --prompt-lengths</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 16,256,1024,4096</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --batch-sizes</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1,2,4,8,16,32,64,128</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --batch-prompt-len</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 256</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --max-new-tokens</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 512</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --out-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> results/labs-01-sweep-512</span></span></code></pre></div><p>The script runs two sweeps.</p><ul><li>Prompt length sweep: vary prompt length across <code>[16, 256, 1024, 4096]</code> tokens</li><li>Batch size sweep: fix prompt length at 256 tokens and vary batch size across <code>[1, 2, 4, 8, 16, 32, 64, 128]</code></li></ul><p>The decode loop requests only the final-position logits with <code>logits_to_keep=1</code>. This avoids allocating full prompt logits during prefill, which would otherwise dominate memory use at large batch sizes.</p><p>Output files:</p><ul><li><a href="results/labs-01-sweep-512/prompt_length_sweep.csv">prompt_length_sweep.csv</a></li><li><a href="results/labs-01-sweep-512/prompt_length_sweep.svg">prompt_length_sweep.svg</a></li><li><a href="results/labs-01-sweep-512/batch_size_sweep.csv">batch_size_sweep.csv</a></li><li><a href="results/labs-01-sweep-512/batch_size_sweep.svg">batch_size_sweep.svg</a></li><li><a href="./results/labs-01-sweep-512/dmon">nvidia-smi dmon logs</a></li></ul><h3 id="prompt-length-sweep" tabindex="-1">Prompt Length Sweep <a class="header-anchor" href="#prompt-length-sweep" aria-label="Permalink to &quot;Prompt Length Sweep&quot;">​</a></h3><p>Increasing prompt length makes the prefill phase longer. As a result, TTFT, or Time To First Token, grows with the number of prompt tokens.</p><p>TPOT, or Time Per Output Token, measures per-token latency during the decode phase. During decode, each token step repeatedly reads model weights, which is the dominant cost in this setup. The KV cache grows with prompt length, but its additional read cost is relatively small in this experiment. Therefore, TPOT changes very little as prompt length increases.</p><p><img src="`+l+'" alt="Prompt length sweep"></p><table tabindex="0"><thead><tr><th style="text-align:right;">Prompt tokens</th><th style="text-align:right;">TTFT ms</th><th style="text-align:right;">TPOT mean ms</th><th style="text-align:right;">Aggregate throughput tok/s</th></tr></thead><tbody><tr><td style="text-align:right;">16</td><td style="text-align:right;">13.9</td><td style="text-align:right;">12.0</td><td style="text-align:right;">83.5</td></tr><tr><td style="text-align:right;">256</td><td style="text-align:right;">28.0</td><td style="text-align:right;">12.0</td><td style="text-align:right;">83.3</td></tr><tr><td style="text-align:right;">1024</td><td style="text-align:right;">73.2</td><td style="text-align:right;">12.2</td><td style="text-align:right;">81.8</td></tr><tr><td style="text-align:right;">4096</td><td style="text-align:right;">297.4</td><td style="text-align:right;">12.5</td><td style="text-align:right;">79.7</td></tr></tbody></table><p>Observations:</p><ul><li>TTFT grows quasi-linearly with prompt length.</li><li>TPOT stays nearly flat, moving only from 12.0ms to 12.5ms.</li><li>Longer prompts slightly reduce total throughput, but that effect mostly comes from including TTFT in the average rather than from decode TPOT itself.</li></ul><h3 id="batch-size-sweep" tabindex="-1">Batch Size Sweep <a class="header-anchor" href="#batch-size-sweep" aria-label="Permalink to &quot;Batch Size Sweep&quot;">​</a></h3><p>With a fixed prompt length of 256 tokens, increasing batch size lets each decode step compute the next token for multiple sequences at once. Per-token latency stays near a plateau for a while, while aggregate throughput across the batch increases substantially.</p><p>GPU utilization is sampled with <code>nvidia-smi dmon -s pucvmet</code> during each batch run.</p><p><img src="'+I+`" alt="Batch size sweep"></p><table tabindex="0"><thead><tr><th style="text-align:right;">Batch size</th><th style="text-align:right;">TPOT mean ms</th><th style="text-align:right;">Aggregate throughput tok/s</th><th style="text-align:right;">GPU util %</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td style="text-align:right;">12.1</td><td style="text-align:right;">82.7</td><td style="text-align:right;">89.1</td></tr><tr><td style="text-align:right;">2</td><td style="text-align:right;">13.8</td><td style="text-align:right;">145.4</td><td style="text-align:right;">78.3</td></tr><tr><td style="text-align:right;">4</td><td style="text-align:right;">13.3</td><td style="text-align:right;">300.7</td><td style="text-align:right;">77.6</td></tr><tr><td style="text-align:right;">8</td><td style="text-align:right;">13.5</td><td style="text-align:right;">592.2</td><td style="text-align:right;">79.6</td></tr><tr><td style="text-align:right;">16</td><td style="text-align:right;">14.5</td><td style="text-align:right;">1107.0</td><td style="text-align:right;">78.3</td></tr><tr><td style="text-align:right;">32</td><td style="text-align:right;">17.0</td><td style="text-align:right;">1881.1</td><td style="text-align:right;">91.7</td></tr><tr><td style="text-align:right;">64</td><td style="text-align:right;">19.4</td><td style="text-align:right;">3296.7</td><td style="text-align:right;">88.8</td></tr><tr><td style="text-align:right;">128</td><td style="text-align:right;">25.6</td><td style="text-align:right;">5007.5</td><td style="text-align:right;">86.2</td></tr></tbody></table><p>Observations:</p><ul><li>Aggregate throughput increases strongly with batch size, but the gain becomes sublinear at large batches.</li><li>TPOT stays close to a plateau through batch size 16, then rises at batch sizes 32, 64, and 128.</li><li>The transition region for this setup starts around batch size 64 to 128: throughput still increases, but doubling batch size from 64 to 128 only improves aggregate throughput by about 1.5x while TPOT rises from 19.4ms to 25.6ms.</li><li><code>nvidia-smi dmon</code> samples once per second, so short runs can be noisy, but the logs still show that the GPU remains highly utilized during batch runs.</li></ul><h3 id="memory-model-and-oom-boundary" tabindex="-1">Memory Model and OOM Boundary <a class="header-anchor" href="#memory-model-and-oom-boundary" aria-label="Permalink to &quot;Memory Model and OOM Boundary&quot;">​</a></h3><p>For <code>Qwen/Qwen2.5-3B-Instruct</code>, the relevant model config is:</p><table tabindex="0"><thead><tr><th>Field</th><th style="text-align:right;">Value</th></tr></thead><tbody><tr><td>Layers</td><td style="text-align:right;">36</td></tr><tr><td>Query heads</td><td style="text-align:right;">16</td></tr><tr><td>KV heads</td><td style="text-align:right;">2</td></tr><tr><td>Head dim</td><td style="text-align:right;">128</td></tr><tr><td>dtype</td><td style="text-align:right;">BF16</td></tr></tbody></table><p>Because the model uses GQA, KV cache size is determined by the number of KV heads, not the number of query heads.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>KV bytes per token</span></span>
<span class="line"><span>= 2(K,V) * 36 layers * 2 KV heads * 128 head_dim * 2 bytes</span></span>
<span class="line"><span>= 36,864 bytes</span></span>
<span class="line"><span>= 36 KiB/token</span></span></code></pre></div><p>For the batch sweep, prompt length is 256 and generation length is 512, so the final sequence length is about 768 tokens.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>batch 128, seq 768:</span></span>
<span class="line"><span>128 * 768 * 36 KiB = 3.375 GiB</span></span></code></pre></div><p>The rough memory budget at batch size 128 is therefore:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>weights:      ~6 GiB</span></span>
<span class="line"><span>KV cache:     ~3.4 GiB</span></span>
<span class="line"><span>other costs:  activations + CUDA context + PyTorch reserved memory + temporary tensors</span></span></code></pre></div><p>One important pitfall is logits allocation during prefill. If the model returns logits for every prompt position, the tensor can be very large:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>batch 128 * seq 256 * vocab 151,936 * 2 bytes</span></span>
<span class="line"><span>= 9.27 GiB</span></span></code></pre></div><p>The sweep script uses <code>logits_to_keep=1</code> because greedy decoding only needs the final-position logits. Without this, batch size 128 can OOM before KV cache becomes the true limiting factor.</p><p>The measured throughput knee around batch size 64 to 128 should therefore be interpreted as the practical saturation region for this setup, not as a pure KV-cache capacity boundary. At that point, throughput still increases, but scaling becomes sublinear and TPOT rises sharply.</p><h3 id="mental-model" tabindex="-1">Mental Model <a class="header-anchor" href="#mental-model" aria-label="Permalink to &quot;Mental Model&quot;">​</a></h3><p>LLM inference can be split into prefill and decode.</p><ul><li>Prefill: processes the full prompt in parallel. As prompt length grows, TTFT increases.</li><li>Decode: generates one token at a time autoregressively. Each token step reads model weights, so decode is often memory-bandwidth bound.</li><li>Batching: groups multiple requests into the same decode step. This lets the system process more tokens per weight read, increasing aggregate throughput.</li></ul><p>The expected pattern is:</p><ul><li>Increasing prompt length: TTFT increases, TPOT stays nearly flat</li><li>Increasing batch size: aggregate throughput increases, TPOT stays flat for a range and then rises once the setup approaches saturation</li></ul><h3 id="recommended-papers" tabindex="-1">Recommended Papers <a class="header-anchor" href="#recommended-papers" aria-label="Permalink to &quot;Recommended Papers&quot;">​</a></h3><ol><li><a href="https://arxiv.org/abs/2211.05102" target="_blank" rel="noreferrer">Efficiently Scaling Transformer Inference</a> (2022.11) — Analyzes the relationship between batch size, model parallelism, and latency vs. throughput.</li><li><a href="https://arxiv.org/abs/2311.18677" target="_blank" rel="noreferrer">Splitwise: Efficient generative LLM inference using phase splitting</a> (2023.11) — Connects the different resource characteristics of prefill and decode to a split serving design.</li></ol>`,45)])])}const M=e(n,[["render",g]]);export{j as __pageData,M as default};
